reference_pwsh:
$py = if ($IsWindows) { 'python' } else { 'python3' }
$p0 = Start-Process $py -ArgumentList 'tools/check.py','cache' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p1 = Start-Process $py -ArgumentList 'tools/check.py','queue' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p2 = Start-Process $py -ArgumentList 'tools/check.py','files' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p0.WaitForExit(); if ($p0.ExitCode -ne 0) { 'cache failed' }
$p1.WaitForExit(); if ($p1.ExitCode -ne 0) { 'queue failed' }
$p2.WaitForExit(); if ($p2.ExitCode -ne 0) { 'files failed' }
